package net.civeira.phylax.features.notification.outbox.infrastructure.smtp;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.mail.EmailMessage;
import net.civeira.phylax.common.infrastructure.mail.EmailService;
import net.civeira.phylax.common.infrastructure.mail.MailConfiguration;
import net.civeira.phylax.features.notification.outbox.domain.gateway.SmtpMailSenderGateway;
import net.civeira.phylax.features.notification.outbox.domain.model.OutboundMail;

/**
 * Adapts {@link SmtpMailSenderGateway} to the existing {@link EmailService} infrastructure.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class SmtpMailSenderAdapter implements SmtpMailSenderGateway {

  private final EmailService emailService;

  @Override
  public void send(OutboundMail mail) {
    emailService.sendMessage(toEmailMessage(mail));
  }

  @Override
  public void send(MailConfiguration config, OutboundMail mail) {
    emailService.sendMessage(config, toEmailMessage(mail));
  }

  private EmailMessage toEmailMessage(OutboundMail mail) {
    return EmailMessage.builder().targetAddress(mail.getRecipient())
        .subject(mail.getSubjectOptional().orElse("")).htmlContent(mail.getHtmlContent())
        .content(mail.getTextContentOptional().orElse(mail.getHtmlContent())).build();
  }
}
